import sys

def main():
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.is_end = False

    root = TrieNode()

    n = int(sys.stdin.readline().strip())
    for _ in range(n):
        password = sys.stdin.readline().strip()
        node = root
        for char in password:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    q = int(sys.stdin.readline().strip())
    for _ in range(q):
        new_password = sys.stdin.readline().strip()
        node = root
        valid = True

        for char in new_password:
            if char not in node.children:
                # Continue to next query
                break
            node = node.children[char]
            if node.is_end:
                valid = False
                break
        else:
            # Check if current node is end of a password
            if node.is_end:
                valid = False

        if not valid:
            print("Invalid")
        else:
            print("Allowed")

if __name__ == "__main__":
    main()
